// 只反映本人亲自发邀/领回/答受；发邀者不因别处的实领或接受自动获得任何新消息。
#include "visit_appointment_access.hpp"
#include "visit_appointment_detail.hpp"
namespace hanmo::resident {
Outcome<std::optional<KnownVisitAppointment>> VisitAppointmentAccess::known_visit_appointment(const StableId& observer,const StableId& id) const{
 Integer now=common_.tick();if(state_.version==2){if(!clock_)return {false,{},common_failure("VisitAppointmentActualClockRequired",{},ErrorKind::unsupported_capability).error};auto current=clock_->read_current_moment();if(!current.ok)return {false,{},current.error};now=current.value.half_day_tick;}
 if(!common_.actor(observer))return {false,{},common_failure("UnknownVisitAppointmentObserver",observer).error};const auto* offer=state_.offered.find(id);if(!offer)return {true,{}, {}};KnownVisitAppointment out;out.source_identity=common_.state().identity;out.observer_actor_id=observer;out.invitation_fact_id=id;out.policy_id=offer->policy_id;out.message_fact_id=offer->message_fact_id;out.terms=offer->terms;
 auto finish=[&]()->Outcome<std::optional<KnownVisitAppointment>>{if(meetings_){for(const auto& row:meetings_->started.rows())if(row.second.invitation_fact_id==id){out.known_status="meeting";out.meeting_fact_id=row.first;}for(const auto& row:meetings_->cancelled.rows())if(row.second.invitation_fact_id==id){out.known_status="cancelled";out.meeting_fact_id=row.first;}for(const auto& row:meetings_->finished.rows())if(row.second.invitation_fact_id==id){out.known_status=row.second.success?"fulfilled":"interrupted";out.meeting_fact_id=row.first;}}return {true,std::move(out),{}};};
 if(observer==offer->terms.inviter_actor_id){out.perspective=VisitAppointmentPerspective::inviter;out.learned_tick=offer->contact.tick;out.known_status=now>offer->terms.latest_tick?"window_elapsed":"promised";return finish();}
 if(observer!=offer->terms.invitee_actor_id)return {true,{}, {}};const auto* collected=visit_appointment_detail::collected(state_,id);if(!collected||collected->contact.actor_id!=observer)return {true,{}, {}};out.perspective=VisitAppointmentPerspective::invitee;out.collection_fact_id=collected->fact_id;out.learned_tick=collected->contact.tick;out.known_status=now>=offer->terms.accept_before_tick?"acceptance_expired":"collected";if(const auto* accepted=visit_appointment_detail::accepted(state_,id)){if(accepted->actor_id!=observer||accepted->collection_fact_id!=collected->fact_id)return {false,{},common_failure("InvalidVisitAppointmentAcceptance",accepted->fact_id).error};out.acceptance_fact_id=accepted->fact_id;out.known_status=now>offer->terms.latest_tick?"window_elapsed":"accepted";}return finish();
}
Outcome<std::vector<VisitAppointmentOwnCommitment>> VisitAppointmentAccess::own_commitments(const StableId& actor,Integer from,Integer through) const{
 if(!common_.actor(actor)||from<0||through<from||through-from>720)return {false,{},common_failure("InvalidVisitAppointmentCommitmentRange",actor).error};std::vector<VisitAppointmentOwnCommitment> out;
 for(const auto& row:state_.offered.rows()){auto known=known_visit_appointment(actor,row.first);if(!known.ok)return {false,{},known.error};if(!known.value)continue;const auto& k=*known.value;if(k.known_status=="cancelled"||k.known_status=="fulfilled"||k.known_status=="interrupted")continue;const auto& t=k.terms;if(!visit_appointment_detail::overlap(from,through,t.earliest_tick,t.latest_tick))continue;StableId source;Integer committed=0;if(k.perspective==VisitAppointmentPerspective::inviter){source=k.invitation_fact_id;committed=t.offered_tick;}else{if(k.acceptance_fact_id.empty())continue;const auto* a=state_.accepted.find(k.acceptance_fact_id);if(!a)return {false,{},common_failure("InvalidVisitAppointmentAcceptance",k.acceptance_fact_id).error};source=a->fact_id;committed=a->tick;}out.push_back({common_.state().identity,actor,k.invitation_fact_id,source,k.perspective==VisitAppointmentPerspective::inviter?t.invitee_actor_id:t.inviter_actor_id,t.place_id,committed,t.earliest_tick,t.latest_tick,t.duration_ticks});}
 return {true,std::move(out),{}};
}
}
